//! Minecraft 26.2 (protocol 776) inputs.
//!
//! minecraft-data has no released 26.2 data. The 26.2 tables are generated by the same code as
//! 26.1 ([`crate::v26_1`]) from minecraft-data-shaped JSON that is synthesised here:
//!
//! - ids, names, block-state ranges, defaults and the property layout come from the jar, through
//!   the committed oracle dumps (`tests/golden/26.2/`: the voxel dump's block and state lines,
//!   the item dump, the entity size dump);
//! - display data minecraft-data has and the jar dumps do not (display names, blast resistance,
//!   light emission / filtering, transparency, entity categories) is taken from minecraft-data
//!   `pc/26.1` by registry name, so it is the same as 26.1 for everything that exists in both;
//! - the blocks, items and entities new in 26.2 take that display data from [`NEW_BLOCKS`],
//!   [`NEW_ITEMS`] and [`NEW_ENTITIES`] (names from the 26.2 jar's `en_us` language file, block
//!   properties from the 26.2 `Blocks` registrations, see each entry).
//!
//! [`synthesise`] run on the 26.1 dumps reproduces minecraft-data's 26.1 block, item and entity
//! layout exactly (`tests::synthesis_reproduces_26_1`), which is the check that the derivation
//! from the dumps is right.

use std::collections::BTreeMap;
use std::path::Path;

use serde_json::{Map, Value, json};

use crate::generate::oracle_lines;
use crate::model::Paths;

type R<T> = Result<T, String>;

/// Oracle dumps of the 26.2 jar.
pub const ORACLE_VOXELS: &str = "tests/golden/26.2/voxel_shapes.jsonl.gz";

/// A block new in 26.2: its display name (`block.minecraft.<name>` of the 26.2 `en_us`) and
/// the 26.1 block whose minecraft-data display fields (resistance, light, transparency,
/// diggable) it shares, because its `Blocks` registration has the same properties.
pub struct NewBlock {
    pub name: &'static str,
    pub display_name: &'static str,
    pub like: &'static str,
}

