const fn nb(name: &'static str, display_name: &'static str, like: &'static str) -> NewBlock {
    NewBlock {
        name,
        display_name,
        like,
    }
}

/// Display names of the items new in 26.2 that are not block items (block items take the
/// block's name, as in minecraft-data): `item.minecraft.<name>` of the 26.2 `en_us`.
pub const NEW_ITEMS: &[(&str, &str)] = &[
    ("music_disc_bounce", "Music Disc"),
    ("sulfur_cube_bucket", "Bucket of Sulfur Cube"),
    ("sulfur_cube_spawn_egg", "Sulfur Cube Spawn Egg"),
];

/// Entities new in 26.2: `(name, display name, minecraft-data type, category)`. The sulfur cube
/// is registered in `EntityTypes` with `MobCategory.MONSTER`, filed like the slime.
pub const NEW_ENTITIES: &[(&str, &str, &str, &str)] =
    &[("sulfur_cube", "Sulfur Cube", "mob", "Hostile mobs")];

/// minecraft-data-shaped `blocks`, `items` and `entities` for the version whose oracle dumps sit
/// next to `voxels`, display data from `md` (minecraft-data `pc/26.1`) and the `NEW_*` tables.
pub fn synthesise(md: &Paths, voxels: &Path) -> R<BTreeMap<String, Value>> {
    let md_blocks = by_name(&md.json("blocks")?)?;
    let md_items = by_name(&md.json("items")?)?;
    let md_entities = by_name(&md.json("entities")?)?;

    // --- blocks: names / ranges / defaults from the block lines, layout from the states ---
    let lines = oracle_lines(voxels)?;
    let mut blocks: Vec<Map<String, Value>> = Vec::new();
    let mut ranges: Vec<(u64, u64)> = Vec::new();
    let mut states: Vec<String> = Vec::new();
    for v in &lines {
        match v["type"].as_str() {
            Some("block") => {
                let name = short(v["name"].as_str().ok_or("block name")?);
                let first = v["first_state"].as_u64().ok_or("first_state")?;
                let count = v["states"].as_u64().ok_or("states")?;
                let mut b = display_of_block(&md_blocks, &name)?;
                b.insert("id".into(), json!(blocks.len()));
                b.insert("name".into(), json!(name));
                b.insert("minStateId".into(), json!(first));
                b.insert("maxStateId".into(), json!(first + count - 1));
                b.insert("defaultState".into(), v["default_state"].clone());
                blocks.push(b);
                ranges.push((first, count));
            }
            Some("state") => {
                let id = v["id"].as_u64().ok_or("state id")? as usize;
                if id != states.len() {
                    return Err(format!("state lines out of order at {id}"));
                }
                states.push(v["state"].as_str().ok_or("state string")?.to_owned());
            }
            _ => {}
        }
    }
    for (b, &(first, count)) in blocks.iter_mut().zip(&ranges) {
        let range = &states[first as usize..(first + count) as usize];
        b.insert("states".into(), Value::Array(layout(range)?));
    }

    // --- items ---
    let item_lines = oracle_lines(&voxels.with_file_name("items.jsonl.gz"))?;
    let block_names: BTreeMap<String, String> = blocks
        .iter()
        .map(|b| {
            (
                b["name"].as_str().unwrap_or_default().to_owned(),
                b["displayName"].as_str().unwrap_or_default().to_owned(),
            )
        })
        .collect();
    let mut items = Vec::new();
    for v in item_lines
        .iter()
        .filter(|v| v["type"].as_str() == Some("item"))
    {
        let name = v["name"].as_str().ok_or("item name")?.to_owned();
        let display = match md_items.get(&name) {
            Some(m) => m["displayName"].clone(),
            None => match NEW_ITEMS.iter().find(|(n, _)| *n == name) {
                Some((_, d)) => json!(d),
                None => match v["block"].as_str().and_then(|b| block_names.get(b)) {
                    Some(d) => json!(d),
                    None => return Err(format!("26.2 item {name}: no display name")),
                },
            },
        };
        let mut it = Map::new();
        it.insert("id".into(), v["id"].clone());
        it.insert("name".into(), json!(name));
        it.insert("displayName".into(), display);
        it.insert("stackSize".into(), v["max_stack_size"].clone());
        if let Some(d) = v["max_damage"].as_u64() {
            it.insert("maxDurability".into(), json!(d));
        }
        items.push(Value::Object(it));
    }

    // --- entities ---
    let ent_lines = oracle_lines(&voxels.with_file_name("entity_sizes.jsonl.gz"))?;
    let mut entities = Vec::new();
    for v in ent_lines
        .iter()
        .filter(|v| v["type"].as_str() == Some("entity_type"))
    {
        let name = short(v["name"].as_str().ok_or("entity name")?);
        let mut e = Map::new();
        e.insert("id".into(), v["id"].clone());
        e.insert("name".into(), json!(name));
        match md_entities.get(&name) {
            Some(m) => {
                for k in ["displayName", "type", "category", "width", "height"] {
                    if let Some(x) = m.get(k) {
                        e.insert(k.into(), x.clone());
                    }
                }
            }
            None => {
                let (_, d, t, c) = NEW_ENTITIES
                    .iter()
                    .find(|x| x.0 == name)
                    .ok_or_else(|| format!("26.2 entity {name}: no display data"))?;
                e.insert("displayName".into(), json!(d));
                e.insert("type".into(), json!(t));
                e.insert("category".into(), json!(c));
            }
        }
        entities.push(Value::Object(e));
    }

    // --- collision shapes (cross-check only): pc/26.1's, new blocks with their analogue's ---
    let mut shapes = md.json("blockCollisionShapes")?;
    if let Some(m) = shapes["blocks"].as_object_mut() {
        for n in NEW_BLOCKS {
            if let Some(x) = m.get(n.like).cloned() {
                m.insert(n.name.to_owned(), x);
            }
        }
    }

    Ok(BTreeMap::from([
        ("blockCollisionShapes".to_owned(), shapes),
        (
            "blocks".to_owned(),
            Value::Array(blocks.into_iter().map(Value::Object).collect()),
        ),
        ("items".to_owned(), Value::Array(items)),
        ("entities".to_owned(), Value::Array(entities)),
    ]))
}

fn short(n: &str) -> String {
    n.trim_start_matches("minecraft:").to_owned()
}

fn by_name(v: &Value) -> R<BTreeMap<String, Map<String, Value>>> {
    v.as_array()
        .ok_or("expected an array")?
        .iter()
        .map(|x| {
            let o = x.as_object().ok_or("expected objects")?.clone();
            let n = o["name"].as_str().ok_or("name")?.to_owned();
            Ok((n, o))
        })
        .collect()
}

/// The minecraft-data display fields of a block: its own 26.1 entry, or its `NEW_BLOCKS`
/// analogue's with the new name. Ids that point into other registries (drops, harvest tools)
/// are left out: they are not used by the modern tables and would be 26.1 ids.
fn display_of_block(
    md: &BTreeMap<String, Map<String, Value>>,
    name: &str,
) -> R<Map<String, Value>> {
    let (src, display) = match md.get(name) {
        Some(m) => (m, None),
        None => {
            let n = NEW_BLOCKS
                .iter()
                .find(|n| n.name == name)
                .ok_or_else(|| format!("26.2 block {name}: neither in pc/26.1 nor NEW_BLOCKS"))?;
            let like = md
                .get(n.like)
                .ok_or_else(|| format!("{name}: analogue {} not in pc/26.1", n.like))?;
            (like, Some(n.display_name))
        }
    };
    let mut out = Map::new();
    for k in [
        "displayName",
        "hardness",
        "resistance",
        "stackSize",
        "diggable",
        "material",
        "transparent",
        "emitLight",
        "filterLight",
        "boundingBox",
    ] {
        if let Some(x) = src.get(k) {
            out.insert(k.into(), x.clone());
        }
    }
    if let Some(d) = display {
        out.insert("displayName".into(), json!(d));
    }
    Ok(out)
}

/// minecraft-data `states` (property layout) of one block from its state strings in id order
/// (`minecraft:x[a=1,b=true]`): properties in string order, values in order of first
/// appearance (the jar enumerates states as the product of the properties, first slowest).
fn layout(states: &[String]) -> R<Vec<Value>> {
    let props = |s: &str| -> Vec<(String, String)> {
        s.split_once('[')
            .map(|(_, rest)| {
                rest.trim_end_matches(']')
                    .split(',')
                    .filter_map(|kv| kv.split_once('='))
                    .map(|(k, v)| (k.to_owned(), v.to_owned()))
                    .collect()
            })
            .unwrap_or_default()
    };
    let first = props(&states[0]);
    let mut values: Vec<Vec<String>> = vec![Vec::new(); first.len()];
    for s in states {
        let p = props(s);
        if p.len() != first.len() || p.iter().zip(&first).any(|(a, b)| a.0 != b.0) {
            return Err(format!(
                "state {s}: property names differ from {}",
                states[0]
            ));
        }
        for (i, (_, v)) in p.into_iter().enumerate() {
            if !values[i].contains(&v) {
                values[i].push(v);
            }
        }
    }
    let product: usize = values.iter().map(Vec::len).product();
    if product != states.len() {
        return Err(format!(
            "{}: {product} combinations, {} states",
            states[0],
            states.len()
        ));
    }
    Ok(first
        .iter()
        .zip(values)
        .map(|((name, _), vals)| {
            let ty = if vals == ["true", "false"] {
                "bool"
            } else if vals.iter().all(|v| v.parse::<i64>().is_ok()) {
                "int"
            } else {
                "enum"
            };
            let mut p = json!({ "name": name, "type": ty, "num_values": vals.len() });
            if ty != "bool" {
                p["values"] = json!(vals);
            }
            p
        })
        .collect())
}

/// Generates `generated/v26_2/` with the 26.1 generator from the synthesised inputs: the
/// tables have the 26.1 layout, the emitted paths and headers name 26.2.
pub fn generate(md: Paths, root: &Path, notes: &mut Vec<String>) -> R<Vec<(String, String)>> {
    let voxels = root.join(ORACLE_VOXELS);
    let synth = synthesise(&md, &voxels)?;
    let p = md.with_overrides(synth);
    let mut own = Vec::new();
    let files = crate::v26_1::generate(&p, &voxels, &mut own)?;
    notes.extend(own.into_iter().map(|n| format!("[26.2] {n}")));
    Ok(files
        .into_iter()
        .map(|(path, text)| {
            let path = path.replacen("v26_1/", "v26_2/", 1);
            (path, retarget(&text))
        })
        .collect())
}

/// Rewrites a 26.1 generated file for 26.2: module paths, version labels in the header, and
/// the provenance of the synthesised minecraft-data files.
fn retarget(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for line in text.split_inclusive('\n') {
        if line.starts_with("//") {
            let l = line
                .replace(
                    "pc/26.1/blocks.json",
                    "tests/golden/26.2 dumps + pc/26.1/blocks.json display fields (codegen/data/src/v26_2.rs)",
                )
                .replace(
                    "pc/26.1/entities.json",
                    "tests/golden/26.2 dumps + pc/26.1/entities.json display fields (codegen/data/src/v26_2.rs)",
                )
                .replace(
                    "26.1/items.json",
                    "26.1/items.json display names (codegen/data/src/v26_2.rs)",
                )
                .replace("tests/golden/26.1/", "tests/golden/26.2/")
                .replace("Minecraft 26.1 ", "Minecraft 26.2 ")
                .replace("Generated 26.1 ", "Generated 26.2 ")
                .replace("//! 26.1 ", "//! 26.2 ");
            out.push_str(&l);
        } else {
            out.push_str(&line.replace("crate::v26_1::", "crate::v26_2::"));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The derivation from the dumps, run on the 26.1 dumps, gives minecraft-data's 26.1 block
    /// layout, item and entity ids (needs the minecraft-data cache).
    #[test]
    fn synthesis_reproduces_26_1() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let data = root.join(".cache/minecraft-data/3.119.0/package/minecraft-data/data");
        let Ok(md) = Paths::new(&data, "26.1") else {
            eprintln!("skipped: no minecraft-data cache");
            return;
        };
        let synth = synthesise(&md, &root.join(crate::v26_1::ORACLE_VOXELS)).unwrap();
        let blocks = crate::model::blocks(&synth["blocks"]).unwrap();
        let want = crate::model::blocks(&md.json("blocks").unwrap()).unwrap();
        assert_eq!(blocks.len(), want.len());
        for (a, b) in blocks.iter().zip(&want) {
            assert_eq!(
                (&a.name, a.id, a.min_state, a.max_state, a.default_state),
                (&b.name, b.id, b.min_state, b.max_state, b.default_state)
            );
            let pa: Vec<_> = a.props.iter().map(|p| (&p.name, &p.values)).collect();
            let pb: Vec<_> = b.props.iter().map(|p| (&p.name, &p.values)).collect();
            assert_eq!(pa, pb, "{}", a.name);
            assert_eq!(a.display_name, b.display_name);
            assert_eq!(
                (a.resistance, a.emit_light, a.filter_light),
                (b.resistance, b.emit_light, b.filter_light)
            );
        }
        let items = crate::model::items(&synth["items"]).unwrap();
        let want = crate::model::items(&md.json("items").unwrap()).unwrap();
        assert_eq!(items.len(), want.len());
        for (a, b) in items.iter().zip(&want) {
            assert_eq!(
                (&a.name, a.id, &a.display_name),
                (&b.name, b.id, &b.display_name)
            );
        }
        let ents = crate::model::entities(&synth["entities"]).unwrap();
        let want = crate::model::entities(&md.json("entities").unwrap()).unwrap();
        assert_eq!(ents.len(), want.len());
        for (a, b) in ents.iter().zip(&want) {
            assert_eq!(
                (&a.name, a.id, a.kind, &a.category),
                (&b.name, b.id, b.kind, &b.category)
            );
        }
    }
}
